{'code': "from qgis.PyQt.QtWidgets import QAction, QMenu
mw = iface.mainWindow()
matches = []
for a in mw.findChildren(QAction):
    t = a.text().replace('&','')
    if '解除' in t or 'Deselect' in a.objectName() or 'deselect' in t.lower():
        parents = []
        try:
            for o in a.associatedObjects():
                if isinstance(o, QMenu):
                    parents.append('menu:' + (o.title() or o.objectName()))
                else:
                    parents.append(type(o).__name__)
        except Exception:
            pass
        matches.append({'objectName': a.objectName(), 'text': t, 'enabled': a.isEnabled(), 'parents': parents})
result = matches"}
